#include <stdio.h>

int main() {
    int original = 121;
    int n = original;
    int reverse = 0;

    while (n > 0) {
        reverse = reverse * 10 + n % 10;
        n /= 10;
    }

    if (original == reverse) {
        printf("Palindrome");
    } else {
        printf("Not Palindrome");
    }
}

